+interface TextNode {
+  type: "text";
+  value: string;
+}
+
+interface InterpolationNode {
+  type: "interpolation";
+  path: string;
+  escaped: boolean;
+}
+
+interface BlockNode {
+  type: "block";
+  kind: "if" | "each";
+  path: string;
+  body: Node[];
+  alternate: Node[] | null;
+}
+
+interface Frame {
+  value: unknown;
+  index?: number;
+}
+
+function position(source: string, offset: number): string {
+  const prior = source.slice(0, offset);
+  return `line ${prior.split("\n").length}, column ${offset - prior.lastIndexOf("\n")}`;
+}
+
+function syntaxError(source: string, offset: number, message: string): Error {
+  return new Error(`${message} at ${position(source, offset)}`);
+}
+
+function parse(template: string): Node[] {
+  let cursor = 0;
+
+  function parseNodes(stop?: string): { nodes: Node[]; stoppedBy?: "else" | "close" } {
+    const nodes: Node[] = [];
+    while (cursor < template.length) {
+      const start = template.indexOf("{{", cursor);
+      if (start < 0) {
+        nodes.push({ type: "text", value: template.slice(cursor) });
+        cursor = template.length;
+        break;
+      }
+      if (start > cursor) nodes.push({ type: "text", value: template.slice(cursor, start) });
+
+      const triple = template.startsWith("{{{", start);
+      const close = triple ? "}}}" : "}}";
+      const end = template.indexOf(close, start + (triple ? 3 : 2));
+      if (end < 0) throw syntaxError(template, start, "Unclosed tag");
+      const raw = template.slice(start + (triple ? 3 : 2), end).trim();
+      cursor = end + close.length;
+
+      if (triple) {
+        if (!raw) throw syntaxError(template, start, "Empty interpolation");
+        nodes.push({ type: "interpolation", path: raw, escaped: false });
+        continue;
+      }
+      if (raw.startsWith("!")) continue;
+      if (raw === "else") {
+        if (!stop) throw syntaxError(template, start, "else outside a block");
+        return { nodes, stoppedBy: "else" };
+      }
+      if (raw.startsWith("/")) {
+        const name = raw.slice(1).trim();
+        if (!stop) throw syntaxError(template, start, `Unexpected closing tag ${name}`);
+        if (name !== stop) throw syntaxError(template, start, `Mismatched closing tag ${name}; expected ${stop}`);
+        return { nodes, stoppedBy: "close" };
+      }
+      if (raw.startsWith("#")) {
+        const [kind, ...pathParts] = raw.slice(1).trim().split(/\s+/);
+        const path = pathParts.join(" ");
+        if ((kind !== "if" && kind !== "each") || !path || pathParts.length !== 1) {
+          throw syntaxError(template, start, `Unknown or invalid block ${raw}`);
+        }
+        const bodyResult = parseNodes(kind);
+        let alternate: Node[] | null = null;
+        if (bodyResult.stoppedBy === "else") {
+          const alternateResult = parseNodes(kind);
+          if (alternateResult.stoppedBy !== "close") throw syntaxError(template, start, `Unclosed ${kind} block`);
+          alternate = alternateResult.nodes;
+        } else if (bodyResult.stoppedBy !== "close") {
+          throw syntaxError(template, start, `Unclosed ${kind} block`);
+        }
+        nodes.push({ type: "block", kind, path, body: bodyResult.nodes, alternate });
+        continue;
+      }
+      if (!raw) throw syntaxError(template, start, "Empty interpolation");
+      nodes.push({ type: "interpolation", path: raw, escaped: true });
+    }
+    return { nodes };
+  }
+
+  return parseNodes().nodes;
+}
+
+function lookup(path: string, root: unknown, frames: Frame[]): unknown {
+  if (path === "this") return frames.at(-1)?.value;
+  if (path === "@index") return frames.at(-1)?.index;
+  const parts = path.split(".");
+  let value: unknown = root;
+  for (const part of parts) {
+    if (value === null || value === undefined || (typeof value !== "object" && typeof value !== "function")) return undefined;
+    value = (value as Record<string, unknown>)[part];
+  }
+  return value;
+}
+
+function isTruthy(value: unknown): boolean {
+  return Boolean(value) && (!Array.isArray(value) || value.length > 0);
+}
+
+function stringify(value: unknown): string {
+  if (value === null || value === undefined) return "";
+  if (typeof value === "object" || typeof value === "function") {
+    throw new Error("Cannot render an object or function as scalar text");
+  }
+  return String(value);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!);
+}
+
+function renderNodes(nodes: Node[], root: unknown, frames: Frame[]): string {
+  return nodes.map((node) => {
+    if (node.type === "text") return node.value;
+    if (node.type === "interpolation") {
+      const text = stringify(lookup(node.path, root, frames));
+      return node.escaped ? escapeHtml(text) : text;
+    }
+    const value = lookup(node.path, root, frames);
+    if (node.kind === "if") return renderNodes(isTruthy(value) ? node.body : (node.alternate ?? []), root, frames);
+    if (!Array.isArray(value) || value.length === 0) return renderNodes(node.alternate ?? [], root, frames);
+    return value.map((item, index) => renderNodes(node.body, root, [...frames, { value: item, index }])).join("");
+  }).join("");
+}
+
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), data, []);
+}
