+import { expect, test } from "bun:test";
+import { render } from "./engine";
+
+test("interpolates escaped and raw values", () => {
+  expect(render("{{value}}|{{{value}}}", { value: "<&>\"'" })).toBe("&lt;&amp;&gt;&quot;&#39;|<&>\"'");
+});
+
+test("preserves whitespace and strips comments", () => {
+  expect(render(" a {{! ignored }} b ", {})).toBe(" a  b ");
+});
+
+test("supports nested conditionals and false values", () => {
+  expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: 0 })).toBe("AC");
+  expect(render("{{#if list}}yes{{else}}no{{/if}}", { list: [] })).toBe("no");
+});
+
+test("supports nested loops with root fallback", () => {
+  const template = "{{#each groups}}{{title}}:{{#each this}}{{this}}@{{@index}}/{{title}};{{/each}}{{else}}none{{/each}}";
+  expect(render(template, { title: "root", groups: [["a", "b"]] })).toBe("root:a@0/root;b@1/root;");
+});
+
+test("renders missing values empty and rejects non-scalars", () => {
